  }
];

export const calculateBmi = (heightCm: number, weightKg: number): BmiCalculationResult => {
  const safeHeight = Math.max(heightCm, 1);
  const safeWeight = Math.max(weightKg, 0);

  const heightM = safeHeight / 100;
  const heightM2 = heightM * heightM;

  const rawBmi = heightM > 0 ? safeWeight / heightM2 : 0;
  const bmi = roundToOneDecimal(rawBmi);

  const standardWeight = roundToOneDecimal(heightM2 * 22);
  const weightDiff = roundToOneDecimal(safeWeight - standardWeight);

  const normalWeightRange = {
    min: roundToOneDecimal(heightM2 * 18.5),
    max: roundToOneDecimal(heightM2 * 25.0)
  };

  const matchedCategory =
    BMI_CATEGORIES.find((cat) => bmi >= cat.min && bmi < cat.max) ||
    BMI_CATEGORIES[BMI_CATEGORIES.length - 1];

  return {
    bmi,
    standardWeight,
    weightDiff,
    normalWeightRange,
    category: matchedCategory
  };
};

import { GaugeProps } from '../types';

interface SegmentDef {
  label: string;
  min: number;
  max: number;
  color: string;
}

const GAUGE_MIN = 10;
const GAUGE_MAX = 40;
const GAUGE_RANGE = GAUGE_MAX - GAUGE_MIN;

const SEGMENTS: SegmentDef[] = [
  { label: '低体重', min: 10, max: 18.5, color: '#3b82f6' },
  { label: '普通体重', min: 18.5, max: 25.0, color: '#10b981' },
  { label: '肥満(1度)', min: 25.0, max: 30.0, color: '#f59e0b' },
  { label: '肥満(2度以上)', min: 30.0, max: 40.0, color: '#ef4444' }
];

const TICKS = [18.5, 25.0, 30.0];

const BmiGauge = ({ currentBmi = 0 }: GaugeProps) => {
  const safeBmi = typeof currentBmi === 'number' && !isNaN(currentBmi) ? currentBmi : 0;
  const clampedBmi = Math.min(Math.max(safeBmi, GAUGE_MIN), GAUGE_MAX);
  const pointerPercentage = ((clampedBmi - GAUGE_MIN) / GAUGE_RANGE) * 100;

  return (
    <div className="gauge-container">
      {/* 境界目盛りラベル */}
      <div style={{ position: 'relative', width: '100%', height: '18px', marginBottom: '4px' }}>
        {TICKS.map((tick) => {
          const tickLeftPercent = ((tick - GAUGE_MIN) / GAUGE_RANGE) * 100;
          return (
            <span
              key={tick}
              style={{
                position: 'absolute',
                left: `${tickLeftPercent}%`,
                transform: 'translateX(-50%)',
                fontSize: '0.75rem',
                fontWeight: 600,
                color: 'var(--text-muted)'
              }}
            >
              {tick}
            </span>
          );
        })}
      </div>

      <div className="gauge-bar">
        {SEGMENTS.map((seg, idx) => {
          const segmentWidthPercent = ((seg.max - seg.min) / GAUGE_RANGE) * 100;
          return (
            <div
              key={idx}
              className="gauge-segment"
              style={{ width: `${segmentWidthPercent}%`, backgroundColor: seg.color }}
              title={seg.label}
            />
          );
        })}
      </div>

      <div
        className="gauge-pointer"
        style={{ left: `${pointerPercentage}%` }}
      >
        <span
          className="gauge-pointer-label"
          style={{
            left: '50%',
            transform: `translateX(-${pointerPercentage}%)`
          }}
        >
          BMI {safeBmi.toFixed(1)}
        </span>
      </div>
    </div>
  );
};

export default BmiGauge;

import { useState, useMemo, ChangeEvent } from 'react';
import { calculateBmi, BMI_CATEGORIES } from './utils/bmi';
import BmiGauge from './components/BmiGauge';
import { InputLimitConfig } from './types';

const HEIGHT_CONFIG: InputLimitConfig = {
  min: 50,
  max: 250,
  default: 170,
  step: 0.5
};

const WEIGHT_CONFIG: InputLimitConfig = {
  min: 10,
  max: 200,
  default: 65,
  step: 0.1
};

const App = () => {
  const [heightInput, setHeightInput] = useState<string>(String(HEIGHT_CONFIG.default));
  const [weightInput, setWeightInput] = useState<string>(String(WEIGHT_CONFIG.default));

  const parsedHeight = parseFloat(heightInput);
  const parsedWeight = parseFloat(weightInput);

  const safeHeight = isNaN(parsedHeight) ? HEIGHT_CONFIG.default : parsedHeight;
  const safeWeight = isNaN(parsedWeight) ? WEIGHT_CONFIG.default : parsedWeight;

  const result = useMemo(() => calculateBmi(safeHeight, safeWeight), [safeHeight, safeWeight]);

  const handleHeightInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    setHeightInput(e.target.value);
  };

  const handleHeightBlur = () => {
    const num = parseFloat(heightInput);
    if (isNaN(num)) {
      setHeightInput(String(HEIGHT_CONFIG.default));
    } else {
      const clamped = Math.max(HEIGHT_CONFIG.min, Math.min(HEIGHT_CONFIG.max, Math.round(num * 10) / 10));
      setHeightInput(String(clamped));
    }
  };

  const handleHeightSliderChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    if (!isNaN(val)) {
      setHeightInput(String(val));
    }
  };

  const handleHeightStep = (delta: number) => {
    const current = isNaN(parsedHeight) ? HEIGHT_CONFIG.default : parsedHeight;
    const next = Math.max(HEIGHT_CONFIG.min, Math.min(HEIGHT_CONFIG.max, Math.round((current + delta) * 10) / 10));
    setHeightInput(String(next));
  };

  const handleWeightInputChange = (e: ChangeEvent<HTMLInputElement>) => {
    setWeightInput(e.target.value);
  };

  const handleWeightBlur = () => {
    const num = parseFloat(weightInput);
    if (isNaN(num)) {
      setWeightInput(String(WEIGHT_CONFIG.default));
    } else {
      const clamped = Math.max(WEIGHT_CONFIG.min, Math.min(WEIGHT_CONFIG.max, Math.round(num * 10) / 10));
      setWeightInput(String(clamped));
    }
  };

  const handleWeightSliderChange = (e: ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    if (!isNaN(val)) {
      setWeightInput(String(val));
    }
  };

  const handleWeightStep = (delta: number) => {
    const current = isNaN(parsedWeight) ? WEIGHT_CONFIG.default : parsedWeight;
    const next = Math.max(WEIGHT_CONFIG.min, Math.min(WEIGHT_CONFIG.max, Math.round((current + delta) * 10) / 10));
    setWeightInput(String(next));
  };

  const handleReset = () => {
    setHeightInput(String(HEIGHT_CONFIG.default));
    setWeightInput(String(WEIGHT_CONFIG.default));
  };

  const sliderHeight = Math.max(HEIGHT_CONFIG.min, Math.min(HEIGHT_CONFIG.max, safeHeight));
  const sliderWeight = Math.max(WEIGHT_CONFIG.min, Math.min(WEIGHT_CONFIG.max, safeWeight));

  const weightDiffSign = result.weightDiff > 0 ? `+${result.weightDiff}` : `${result.weightDiff}`;

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="header-title">
          <span>⚖️</span>
          <span>BMI・適正体重かんたん判定ツール</span>
        </h1>
        <p className="header-desc">
          身長と体重を入力するだけで、日本肥満学会の基準に基づきBMIと理想体重を即座に計算します。
        </p>
      </header>

      <div className="grid-layout">
        {/* 入力パネル */}
        <section className="card input-section">
          {/* 身長入力 */}
          <div className="input-group">
            <label className="input-label" htmlFor="height-number">
              <span>身長</span>
              <span>範囲: {HEIGHT_CONFIG.min} 〜 {HEIGHT_CONFIG.max} cm</span>
            </label>
            <div className="input-row">
              <input
                id="height-number"
                type="number"
                className="number-input"
                min={HEIGHT_CONFIG.min}
                max={HEIGHT_CONFIG.max}
                step={HEIGHT_CONFIG.step}
                value={heightInput}
                onChange={handleHeightInputChange}
                onBlur={handleHeightBlur}
              />
              <span className="unit-label">cm</span>
            </div>
            <input
              type="range"
              className="range-slider"
              min={HEIGHT_CONFIG.min}
              max={HEIGHT_CONFIG.max}
              step={HEIGHT_CONFIG.step}
              value={sliderHeight}
              onChange={handleHeightSliderChange}
            />
            <div className="quick-buttons">
              <button type="button" className="quick-btn" onClick={() => handleHeightStep(-5)}>-5cm</button>
              <button type="button" className="quick-btn" onClick={() => handleHeightStep(-1)}>-1cm</button>
              <button type="button" className="quick-btn" onClick={() => handleHeightStep(1)}>+1cm</button>
              <button type="button" className="quick-btn" onClick={() => handleHeightStep(5)}>+5cm</button>
            </div>
          </div>

          {/* 体重入力 */}
          <div className="input-group">
            <label className="input-label" htmlFor="weight-number">
              <span>体重</span>
              <span>範囲: {WEIGHT_CONFIG.min} 〜 {WEIGHT_CONFIG.max} kg</span>
            </label>
            <div className="input-row">
              <input
                id="weight-number"
                type="number"
                className="number-input"
                min={WEIGHT_CONFIG.min}
                max={WEIGHT_CONFIG.max}
                step={WEIGHT_CONFIG.step}
                value={weightInput}
                onChange={handleWeightInputChange}
                onBlur={handleWeightBlur}
              />
              <span className="unit-label">kg</span>
            </div>
            <input
              type="range"
              className="range-slider"
              min={WEIGHT_CONFIG.min}
              max={WEIGHT_CONFIG.max}
              step={WEIGHT_CONFIG.step}
              value={sliderWeight}
              onChange={handleWeightSliderChange}
            />
            <div className="quick-buttons">
              <button type="button" className="quick-btn" onClick={() => handleWeightStep(-5)}>-5kg</button>
              <button type="button" className="quick-btn" onClick={() => handleWeightStep(-1)}>-1kg</button>
              <button type="button" className="quick-btn" onClick={() => handleWeightStep(1)}>+1kg</button>
              <button type="button" className="quick-btn" onClick={() => handleWeightStep(5)}>+5kg</button>
            </div>
          </div>

          <button type="button" className="reset-btn" onClick={handleReset}>
            🔄 初期値（{HEIGHT_CONFIG.default}cm / {WEIGHT_CONFIG.default}kg）に戻す
          </button>
        </section>

        {/* 計算結果パネル */}
        <section className="card result-section">
          <div>
            <span
              className="result-badge"
              style={{
                backgroundColor: `${result.category.color}15`,
                color: result.category.color,
                border: `1.5px solid ${result.category.color}`
              }}
            >
              判定: {result.category.label}
            </span>
          </div>

          <div className="result-bmi-value">
            {result.bmi.toFixed(1)}
            <span className="result-bmi-unit">BMI</span>
          </div>

          <BmiGauge currentBmi={result.bmi} />

          <div className="result-meta-grid">
            <div className="meta-box">
              <span className="meta-label">適正体重 (BMI 22)</span>
              <span className="meta-value">{result.standardWeight} kg</span>
            </div>
            <div className="meta-box">
              <span className="meta-label">適正体重との差</span>
              <span
                className="meta-value"
                style={{
                  color: result.weightDiff > 0 ? '#ef4444' : result.weightDiff < 0 ? '#3b82f6' : '#10b981'
                }}
              >
                {weightDiffSign} kg
              </span>
            </div>
            <div className="meta-box" style={{ gridColumn: 'span 2' }}>
              <span className="meta-label">普通体重の範囲 (BMI 18.5 〜 25.0)</span>
              <span className="meta-value">
                {result.normalWeightRange.min} kg 〜 {result.normalWeightRange.max} kg
              </span>
            </div>
          </div>

          <div className="advice-card" style={{ borderLeftColor: result.category.color }}>
            <h3 className="advice-title">
              <span>💡</span>
              <span>健康アドバイス</span>
            </h3>
            <p className="advice-text">{result.category.advice}</p>
          </div>
        </section>
      </div>

      {/* 日本肥満学会の判定基準一覧 */}
      <section className="card" style={{ marginTop: '24px' }}>
        <h2 style={{ fontSize: '1.15rem', fontWeight: 700, marginBottom: '14px', color: '#0f172a' }}>
          肥満度判定基準一覧 (日本肥満学会)
        </h2>
        <div className="category-table-container">
          <table className="category-table">
            <thead>
              <tr>
                <th>判定区分</th>
                <th>BMI範囲</th>
                <th>現在の状態</th>
              </tr>
            </thead>
            <tbody>
              {BMI_CATEGORIES.map((cat) => {
                const isActive = cat.id === result.category.id;
                const rangeText =
                  cat.max === Infinity
                    ? `${cat.min} 以上`
                    : cat.min === 0
                    ? `${cat.max} 未満`
                    : `${cat.min} 〜 ${cat.max} 未満`;

                return (
                  <tr key={cat.id} className={isActive ? 'active-row' : ''}>
                    <td>
                      <span
                        style={{
                          display: 'inline-block',
                          width: '10px',
                          height: '10px',
                          borderRadius: '50%',
                          backgroundColor: cat.color,
                          marginRight: '8px'
                        }}
                      />
                      {cat.label}
                    </td>
                    <td>{rangeText}</td>
                    <td>{isActive ? '● 該当' : '-'}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
};

export default App;
